import React, { useState } from "react";
import { Container, TextField, Button, Typography, Box, Paper, IconButton, InputAdornment, Checkbox, FormControlLabel, AppBar, Toolbar } from "@mui/material";
import { Visibility, VisibilityOff, Home } from "@mui/icons-material";
import { useNavigate } from "react-router-dom";

const Register = () => {
  const navigate = useNavigate();
  const [formData, setFormData] = useState({
    regNumber: "",
    password: "",
    confirmPassword: "",
    showPassword: false,
    showConfirmPassword: false,
    acceptTerms: false,
  });
  const [errors, setErrors] = useState({});

  const handleChange = (e) => {
    const { name, value, type, checked } = e.target;
    const newValue = value.replace(/\s/g, ""); // Prevent spaces in input fields
    setFormData({ ...formData, [name]: type === "checkbox" ? checked : newValue });

    if (name === "regNumber") {
      if (newValue.length !== 8) {
        setErrors({ ...errors, regNumber: "Reg Number must be 8 characters long." });
      } else if (!/^[A-Za-z]\d{6}[A-Za-z]$/.test(newValue)) {
        setErrors({ ...errors, regNumber: "Invalid Reg Number." });
      } else {
        setErrors({ ...errors, regNumber: "" });
      }
    }

    if (name === "password") {
      setErrors({ ...errors, password: newValue ? "" : "Required field" });
    }

    if (name === "confirmPassword") {
      setErrors({
        ...errors,
        confirmPassword: newValue === formData.password ? "" : "Passwords do not match",
      });
    }
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    let newErrors = {};

    if (!formData.regNumber) newErrors.regNumber = "Required field";
    else if (formData.regNumber.length !== 8) newErrors.regNumber = "Reg Number must be 8 characters long.";
    else if (!/^[A-Za-z]\d{6}[A-Za-z]$/.test(formData.regNumber)) newErrors.regNumber = "Invalid Reg Number.";

    if (!formData.password) newErrors.password = "Required field";
    if (!formData.confirmPassword) newErrors.confirmPassword = "Required field";
    if (formData.password !== formData.confirmPassword) newErrors.confirmPassword = "Passwords do not match";
    if (!formData.acceptTerms) newErrors.acceptTerms = "You must accept the terms and conditions.";

    setErrors(newErrors);

    if (Object.keys(newErrors).length === 0) {
      console.log("Registration Successful", formData);
      navigate("/login");
    }
  };

  return (
    <Box sx={{ minHeight: "100vh", background: "rgba(100, 200, 225, 0.3)", backdropFilter: "blur(15px)", display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center" }}>
      {/* Navigation Bar */}
      <AppBar position="fixed" color="primary">
        <Toolbar>
          <IconButton edge="start" color="inherit" onClick={() => navigate("/")}>
            <Home />
          </IconButton>
          <Typography variant="h6" sx={{ cursor: "pointer" }} onClick={() => navigate("/")}>
            SRC E-Voting System
          </Typography>
        </Toolbar>
      </AppBar>

      {/* Registration Form */}
      <Container maxWidth="sm" sx={{ mt: 12 }}>
        <Paper elevation={3} sx={{ p: 4 }}>
          <Typography variant="h5" fontWeight="bold" gutterBottom>
            Register
          </Typography>
          <Box component="form" onSubmit={handleSubmit} sx={{ display: "flex", flexDirection: "column", gap: 2 }}>
            <TextField
              label="Reg Number"
              name="regNumber"
              value={formData.regNumber}
              onChange={handleChange}
              required
              fullWidth
              helperText={errors.regNumber}
              error={!!errors.regNumber}
            />
            <TextField
              label="Password"
              name="password"
              type={formData.showPassword ? "text" : "password"}
              value={formData.password}
              onChange={handleChange}
              required
              fullWidth
              InputProps={{
                endAdornment: (
                  formData.password && (
                    <InputAdornment position="end">
                      <IconButton onClick={() => setFormData({ ...formData, showPassword: !formData.showPassword })} edge="end">
                        {formData.showPassword ? <VisibilityOff /> : <Visibility />}
                      </IconButton>
                    </InputAdornment>
                  )
                ),
              }}
              helperText={errors.password}
              error={!!errors.password}
            />
            <TextField
              label="Confirm Password"
              name="confirmPassword"
              type={formData.showConfirmPassword ? "text" : "password"}
              value={formData.confirmPassword}
              onChange={handleChange}
              required
              fullWidth
              InputProps={{
                endAdornment: (
                  formData.confirmPassword && (
                    <InputAdornment position="end">
                      <IconButton onClick={() => setFormData({ ...formData, showConfirmPassword: !formData.showConfirmPassword })} edge="end">
                        {formData.showConfirmPassword ? <VisibilityOff /> : <Visibility />}
                      </IconButton>
                    </InputAdornment>
                  )
                ),
              }}
              helperText={errors.confirmPassword}
              error={!!errors.confirmPassword}
            />
            <FormControlLabel
              control={<Checkbox checked={formData.acceptTerms} onChange={handleChange} name="acceptTerms" />}
              label="I accept the terms and conditions."
            />
            {errors.acceptTerms && <Typography color="error">{errors.acceptTerms}</Typography>}
            <Button type="submit" variant="contained" color="success" fullWidth sx={{ height: "48px" }}>
              Register
            </Button>
            <Typography variant="body2" align="center" sx={{ mt: 2 }}>
              Already have an account? <a href="/login" style={{ color: "#1565c0", textDecoration: "none" }}>Login</a>
            </Typography>
          </Box>
        </Paper>
      </Container>
    </Box>
  );
};

export default Register;
